    INSERT INTO ielts_tests (slug,name,is_published,description) VALUES ('gri-listening-5','Gri Listening 5',true,'IELTS Academic Listening') RETURNING id INTO v_test;
    INSERT INTO ielts_sections (test_id,section,duration_minutes,audio_url) VALUES (v_test,'listening',30,'https://vazbvbqgvtlaqkytfsbi.supabase.co/storage/v1/object/public/ielts-audio/IELTS-Mock-Test-2025-September-Listening-Practice-Test-1.mp3') RETURNING id INTO v_sec;
    INSERT INTO ielts_parts (section_id,part_number,title,context) VALUES (v_sec,1,'Part 1','A student planning to study in Nice discusses different options for travelling to France with a travel agent.') RETURNING id INTO v_part;
    INSERT INTO ielts_question_groups (part_id,group_order,start_question_number,end_question_number,question_type,instructions,shared_content) VALUES (v_part,1,1,10,'sentence_completion','Complete the notes below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer.','{}'::jsonb) RETURNING id INTO v_grp;
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,1,'Advantage of travelling by train: it is much ______.','"faster"'::jsonb,'["faster"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,2,'Advantage of travelling by train: it is ______.','"more affordable"'::jsonb,'["more affordable"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,3,'Advantage of travelling by train: you can take as much ______ as you need.','"luggage"'::jsonb,'["luggage"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,4,'The Eurostar: runs on schedule ______ of the time.','"92.4 percent"'::jsonb,'["92.4 percent","92.4%"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,5,'The Eurostar: can reach speeds of ______ miles per hour.','"186"'::jsonb,'["186"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,6,'Option 1 from Paris to Nice: catch the TGV train at ______.','"11:46"'::jsonb,'["11:46","11.46"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,7,'Option 2 from Paris to Nice: catch the TGV train at ______ (and travel overnight).','"22:25"'::jsonb,'["22:25","22.25"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,8,'Option 2 from Paris to Nice: catch the later TGV train and travel ______.','"overnight"'::jsonb,'["overnight"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,9,'Single tickets cost approximately ______ the return fare.','"half"'::jsonb,'["half","half of"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,10,'Flying from London to Nice takes ______.','"2 hours"'::jsonb,'["2 hours","two hours"]'::jsonb);
    INSERT INTO ielts_parts (section_id,part_number,title,context) VALUES (v_sec,2,'Part 2','A guide describes the construction of ''the Cube'', a spectacular new architectural development in the city of Birmingham.') RETURNING id INTO v_part;
    INSERT INTO ielts_question_groups (part_id,group_order,start_question_number,end_question_number,question_type,instructions,shared_content) VALUES (v_part,1,11,15,'sentence_completion','Complete the table below. Write NO MORE THAN THREE WORDS AND/OR A NUMBER for each answer.','{}'::jsonb) RETURNING id INTO v_grp;
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,11,'PROJECT DEVELOPMENT SCHEDULE — The Cube — Length of project: ______.','"142 weeks"'::jsonb,'["142 weeks"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,12,'Activity: Completion of each floor — Time frame: each floor takes ______.','"2-3 weeks"'::jsonb,'["2-3 weeks","two to three weeks"]'::jsonb);
