    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,14,'Activity: ''Topping out'' of frame — Time frame: towards the end of ______.','"summer"'::jsonb,'["summer","late summer"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,15,'Activity: Installation of fretwork screen — Time frame: coming together in ______.','"early Autumn"'::jsonb,'["early Autumn","early autumn"]'::jsonb);
