    INSERT INTO ielts_parts (section_id,part_number,title,context) VALUES (v_sec,3,'Part 3','Four students — Lynn, Thomas, Sophie and David — talk about one of their tutors, Marlena.') RETURNING id INTO v_part;
    INSERT INTO ielts_question_groups (part_id,group_order,start_question_number,end_question_number,question_type,instructions,shared_content) VALUES (v_part,1,21,25,'mcq_single','Which student expresses each of the opinions about their tutor? Choose your answer from the box and write the letters A - D next to questions 21-25.','{}'::jsonb) RETURNING id INTO v_grp;
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,21,'When things don''t make sense I think it''s my mistake at first.','[{"letter":"A","text":"David"},{"letter":"B","text":"Thomas"},{"letter":"C","text":"Sophie"},{"text":"Lynn","letter":"D"}]'::jsonb,'"D"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,22,'I find the tutor''s mistakes entertaining.','[{"letter":"A","text":"David"},{"letter":"B","text":"Thomas"},{"letter":"C","text":"Sophie"},{"text":"Lynn","letter":"D"}]'::jsonb,'"B"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,23,'I think it''s unfortunate when tutors confuse people.','[{"letter":"A","text":"David"},{"letter":"B","text":"Thomas"},{"letter":"C","text":"Sophie"},{"letter":"D","text":"Lynn"}]'::jsonb,'"C"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,24,'I don''t believe the situation is so serious.','[{"text":"David","letter":"A"},{"letter":"B","text":"Thomas"},{"letter":"C","text":"Sophie"},{"letter":"D","text":"Lynn"}]'::jsonb,'"A"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,25,'The professor should be aware of his tutor''s abilities.','[{"text":"David","letter":"A"},{"letter":"B","text":"Thomas"},{"letter":"C","text":"Sophie"},{"letter":"D","text":"Lynn"}]'::jsonb,'"D"'::jsonb);
    INSERT INTO ielts_question_groups (part_id,group_order,start_question_number,end_question_number,question_type,instructions,shared_content) VALUES (v_part,2,26,30,'sentence_completion','Complete the sentences below. Write NO MORE THAN TWO WORDS for each answer.','{}'::jsonb) RETURNING id INTO v_grp;
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,26,'Remember that English is not Marlena''s first language. She doesn''t understand when you''re joking around, so don''t ______ her so much.','"tease"'::jsonb,'["tease"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,27,'If you pick on her, you will make her ______ that she can''t think clearly.','"so nervous"'::jsonb,'["so nervous","nervous"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,28,'If you need help, make an appointment to meet with her ______.','"individually"'::jsonb,'["individually"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,29,'If you meet her privately, you might see a ______ of her.','"different side"'::jsonb,'["different side"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,30,'Remember that tutors are not old academics; she is not yet experienced as a ______.','"teacher"'::jsonb,'["teacher"]'::jsonb);
    INSERT INTO ielts_parts (section_id,part_number,title,context) VALUES (v_sec,4,'Part 4','A lecturer gives an Epidemiology 101 talk about tuberculosis (TB).') RETURNING id INTO v_part;
    INSERT INTO ielts_question_groups (part_id,group_order,start_question_number,end_question_number,question_type,instructions,shared_content) VALUES (v_part,1,31,40,'sentence_completion','Complete the notes below. Write NO MORE THAN THREE WORDS AND/OR A NUMBER for each answer.','{}'::jsonb) RETURNING id INTO v_grp;
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,31,'Tuberculosis is closely associated with the ______.','"AIDS epidemic"'::jsonb,'["AIDS epidemic"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,32,'In the UK: since the 19th century, better living conditions, ______, immunisation and effective treatments have made TB uncommon.','"better nutrition"'::jsonb,'["better nutrition"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,33,'Globally, TB is still common in ______.','"developing countries"'::jsonb,'["developing countries"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,34,'Globally, TB is still common in developing countries and parts of ______.','"Eastern Europe"'::jsonb,'["Eastern Europe"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,35,'TB causes ______ deaths per year; more than any other infectious disease.','"three million"'::jsonb,'["three million","3 million"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,36,'Overall, ______ of the world''s population is infected but not everyone gets sick.','"one third"'::jsonb,'["one third","one-third","a third"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,37,'Risk factor — a weakened immune system due to HIV infection, immune-suppressing treatment, or alcohol or ______.','"drug addiction"'::jsonb,'["drug addiction"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,38,'Risk factor — certain environments: more common among homeless people, prisoners, and people in ______ and in more impoverished areas.','"large cities"'::jsonb,'["large cities"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,39,'Treatment: 50 years ago, a way ______ TB was found.','"to cure"'::jsonb,'["to cure"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,40,'The most recent form of tuberculosis, XDR-TB, poses a ______ to general TB control.','"serious threat"'::jsonb,'["serious threat","threat"]'::jsonb);
